from core import *

def main():
 rows=[];repairs=[];manifest=[]
 for h in HEATS:
  y,t,w=load(h);m=dict(np.load(P/f'data/{h}_masks.npz'));r=dict(np.load(P/f'data/{h}_fit.npz'));D=r['reconstructed'];mask=m['repair'];sat=y==65535;conditional=D.copy();conv=np.zeros(y.shape,bool)
  if sat.any():
   c=np.load(P/f'data/{h}_conditional.npz');conditional[sat]=c['estimate'][sat];conv=c['solver_converged_at_sat']
  q=project_record(y,m['valid'],r['latent'],t,w,True,True)[1];q[sat&~conv]|=8192;q[m['suspect']]|=256;q[mask]|=16384;q[r['numerical_fallback']]|=32768;frame=pd.read_csv(V3/f'results/{h}_frame_diagnostics.csv');q[frame.candidate.to_numpy()]|=1024
  np.savez_compressed(P/f'data/{h}_interface.npz',time=t,wavelength=w,raw=y,cleaned=np.where(mask,np.nan,y),reconstructed=D,latent=r['latent'],conditional=conditional,valid=m['valid'],invalid=mask,quality=q,quality_grade=m['grade'],statistical_repair=mask,suspected_saturation=sat,saturated_unidentifiable=sat,conditional_solver_converged=conv,numerical_fallback=r['numerical_fallback'],score=m['score'],offline=True,interpolation='bilinear',rank=4,eta=.003,hardware_fault_confirmed=False)
  diff=D-y;np.savez_compressed(P/f'data/{h}_difference.npz',difference=diff,repair=mask);model=Spectrum(t,w,D,y,q,conditional);td=np.linspace(t[0],t[-1],2*len(t)-1);wd=np.linspace(w[0],w[-1],2*len(w)-1);dense=model.evaluate(td,wd).astype(np.float32);np.savez_compressed(P/f'data/{h}_dense.npz',time=td,wavelength=wd,recorded=dense,offline=True)
  area=np.trapezoid(y,w,axis=1);after=np.trapezoid(D,w,axis=1);peak=y.max(1);solver=json.loads((P/f'results/{h}_solver.json').read_text());ii,jj=np.where(mask)
  for i,j in zip(ii,jj):repairs.append(dict(heat_id=h,row=int(i),column=int(j),time_s=t[i],wavelength_nm=w[j],original=y[i,j],repaired=D[i,j],difference=diff[i,j],score=float(m['score'][i,j]),numerical_fallback=bool(r['numerical_fallback'][i,j]),measured_value_is_original=True,repaired_value_is_estimate=True))
  rows.append(dict(heat_id=h,observations=y.size,repair_points=int(mask.sum()),actually_changed=int((abs(diff)>1e-8).sum()),repair_fraction=float(mask.mean()),upward_repairs=int((diff>1e-8).sum()),downward_repairs=int((diff< -1e-8).sum()),suspect_retained=int(m['suspect'].sum()),frame_candidates_retained=int(frame.candidate.sum()),whole_frames_deleted=int(mask.all(1).sum()),unchanged_observation_max_error=float(np.max(abs(diff[~mask]))),negative_nodes=int((D<0).sum()),negative_dense=int((dense<0).sum()),top_codes=int(sat.sum()),recorded_top_code_max_error=float(np.max(abs(D[sat]-65535))) if sat.any() else 0.,conditional_lower_violations=int((conditional[sat]<65535).sum()),integral_relative_mae=float(np.mean(abs(after-area)/np.maximum(abs(area),1))),peak_p95_relative_change=float(np.quantile(abs(D.max(1)-peak)/np.maximum(peak,1),.95)),peak_max_relative_change=float(np.max(abs(D.max(1)-peak)/np.maximum(peak,1))),numerical_fallback_points=int(r['numerical_fallback'][mask].sum()),converged=solver['converged'],iterations=len(solver['history']),seconds=solver['seconds']))
  for artifact in ['interface','dense','difference','masks']:path=P/f'data/{h}_{artifact}.npz';manifest.append(dict(heat_id=h,artifact=artifact,sha256=sha(path),bytes=path.stat().st_size))
  pd.DataFrame(rows).to_csv(P/'results/final_summary.csv',index=False);pd.DataFrame(repairs).to_csv(P/'results/actual_repairs.csv',index=False);pd.DataFrame(manifest).to_csv(P/'results/artifact_manifest.csv',index=False);print('export',h,int(mask.sum()),flush=True)
 dump(P/'results/FINAL_COMPLETE.json',dict(heats=10,repair_points=sum(r['repair_points'] for r in rows),actually_changed=sum(r['actually_changed'] for r in rows),whole_frames_deleted=0,model='scale-adaptive multi-evidence statistical point repair + unchanged V3 completion and bilinear spectrum'))
if __name__=='__main__':main()
